from format_lecon import Lesson, paras, table, steps
from antibiotiques_parenteraux import coamoxi, clindamycine

l = Lesson('Infection cervicale profonde', 6)
l.add('Une infection cervicale profonde touche les {espaces situés sous les fascias du cou}. Elle peut rester inflammatoire ou former un abcès. Son extension peut menacer les voies aériennes et les structures voisines.', paras(
    'Le terme décrit un siège anatomique, et non un germe ou un traitement unique. La recommandation SFORL 2024 distingue notamment adénites, abcès péri-amygdaliens, infections péripharyngées et cellulites profondes extensives. Il faut préciser le foyer initial, les espaces atteints et l’existence de pus ou de nécrose. Une simple rougeur cutanée et une infection profonde ne sont pas synonymes.',
    'L’espace parapharyngé se situe à côté du pharynx, l’espace rétropharyngé en arrière. Les enveloppes conjonctives du cou délimitent des compartiments dont les communications favorisent la propagation. Le médiastin est la région centrale du thorax où une infection cervicale peut descendre.',
    'L’angine de Ludwig correspond à une infection diffuse du plancher buccal, souvent d’origine dentaire. L’induration et l’œdème peuvent déplacer la langue et gêner la respiration, même sans collection bien individualisée. Un abcès péri-amygdalien peut rester localisé ou s’étendre plus profondément.'
), (3,34,36))
l.add('Le {contexte du foyer et le terrain} orientent la recherche. Une infection dentaire, pharyngée ou salivaire peut être en cause. L’âge et les comorbidités modifient la présentation et les décisions.', paras(
    'Demander un épisode pharyngé récent, une douleur dentaire, un geste buccal ou cervical, un traumatisme et une pathologie salivaire. Le foyer peut ne plus être évident au moment de l’examen. Une antibiothérapie antérieure peut aussi modifier les résultats microbiologiques.',
    'Chez l’enfant, un torticolis fébrile et un refus de boire doivent faire rechercher une atteinte profonde. Chez l’adulte, les foyers dentaires ou pharyngés et les complications doivent être activement recherchés. Le diabète ou une immunodépression renforcent la vigilance.',
    'Aucune incidence suisse actuelle et aucun rang comparatif entre les dix diagnostics de la tuméfaction du visage ou du cou n’ont été établis dans les sources consultées. Une fréquence hospitalière ou une série spécialisée ne permet pas d’estimer le risque individuel dans la population générale.'
), (3,34,36))
l.add('La {propagation entre les espaces cervicaux} explique les complications. L’œdème peut rétrécir les voies aériennes, tandis que le pus et la nécrose entretiennent le foyer. Les antibiotiques seuls peuvent alors être insuffisants.', paras(
    'L’infection peut diffuser à partir d’un foyer buccopharyngé ou dentaire. L’œdème et l’inflammation réduisent l’espace disponible autour du pharynx et du larynx ; une ouverture de bouche limitée peut compliquer l’accès aux voies aériennes.',
    'Le pus constitue une collection, tandis que la cellulite correspond à une inflammation infectieuse des tissus. Une fasciite atteint les enveloppes conjonctives ; une forme nécrosante détruit des tissus. Ces descriptions ne sont pas interchangeables et guident les gestes de contrôle du foyer.',
    'La proximité de la veine jugulaire interne et de la carotide expose à des complications vasculaires. Une thrombophlébite jugulaire infectée peut s’accompagner d’emboles septiques pulmonaires, notamment dans un syndrome de Lemierre. Une extension descendante peut provoquer une médiastinite.',
    'Une collection mal drainée et des tissus nécrotiques restent des foyers infectieux malgré une exposition antibiotique correcte. À l’inverse, la seule image évocatrice de collection ne suffit pas à déterminer le geste : la gravité et l’avis chirurgical restent décisifs.'
) + table(['Perturbation','Exploration','Réponse thérapeutique'], [
    ['Œdème et rétrécissement pharyngolaryngé','Évaluation respiratoire et examen spécialisé des voies aériennes.','Sécurisation des voies aériennes si nécessaire ; traitement de la cause.'],
    ['Infection bactérienne dans un espace profond','Imagerie topographique et prélèvement du foyer si réalisable.','Antibiothérapie adaptée au siège, au terrain et à la sensibilité.'],
    ['Collection ou tissus nécrotiques entretenant le foyer','Imagerie, évolution clinique et évaluation chirurgicale.','Drainage ou débridement lorsque indiqué, associé au traitement infectieux.'],
    ['Extension médiastinale ou vasculaire','Imagerie cervico-thoracique adaptée à la complication.','Contrôle du foyer et traitement spécialisé multidisciplinaire.']
]), (3,34,36))
l.add('La démarche commence par la {menace respiratoire et le sepsis}. Dyspnée, salive mal déglutie, voix modifiée ou aggravation rapide imposent une évaluation urgente. L’imagerie ne doit pas retarder les gestes vitaux.', table(['Situation','Conduite'], [
    ['Dyspnée, stridor, incapacité à gérer la salive ou épuisement','Appeler le 144 hors hôpital ; mobiliser immédiatement l’équipe capable de sécuriser des voies aériennes difficiles.'],
    ['Hypotension, confusion ou autre signe de défaillance d’organe','Prendre en charge un sepsis en parallèle du foyer et des voies aériennes ; ne pas attendre les cultures pour traiter une urgence.'],
    ['Douleur et gonflement rapidement extensifs, crépitation ou peau suspecte','Demander un avis chirurgical immédiat et rechercher une forme extensive ou nécrosante.'],
    ['Douleur thoracique ou dégradation respiratoire associée','Rechercher une extension médiastinale ou une complication pulmonaire.'],
    ['Patient actuellement stable, mais signes compatibles avec un espace profond atteint','Organiser sans délai une évaluation hospitalière spécialisée et une imagerie adaptée.']
]), (3,34,35,36))
l.add('L’anamnèse reconstitue la {chronologie de l’infection}. Elle précise déglutition, ouverture buccale, respiration et symptômes thoraciques. Les traitements reçus et la nature exacte d’une allergie sont déterminants.', steps(
    'Demander quand ont débuté douleur, fièvre et gonflement, puis préciser leur vitesse d’aggravation.',
    'Rechercher une douleur dentaire ou pharyngée, une infection salivaire, un soin récent, une plaie ou un corps étranger possible.',
    'Demander si le patient peut boire, avaler sa salive, parler et ouvrir la bouche comme d’habitude.',
    'Rechercher torticolis, douleur cervicale inhabituelle, gêne respiratoire et douleur thoracique.',
    'Relever antibiotiques déjà pris, réponse observée, allergies avec délai et manifestations, diabète et immunodépression.',
    'Préciser poids, fonction rénale connue, grossesse ou allaitement et médicaments associés avant la prescription.'
), (3,34,38,39))
l.add('L’examen cherche le {siège et le retentissement sans déstabiliser le patient}. Il apprécie d’abord respiration, circulation et vigilance. Une exploration pharyngée difficile nécessite une équipe et un cadre adaptés.', paras(
    'Observer position, effort respiratoire, voix, déglutition spontanée et salive. Une respiration calme, une voix habituelle, une déglutition sans gêne et une ouverture buccale conservée constituent les repères attendus. Mesurer les constantes et apprécier l’hydratation. Un patient qui ne tolère pas la position couchée ne doit pas être allongé de force pour compléter l’examen.',
    'Examiner le cou, la peau, les dents et le plancher buccal selon la tolérance. Rechercher tuméfaction, induration, asymétrie, trismus et limitation des mouvements. L’absence d’une grosse masse superficielle n’exclut pas un foyer profond.',
    'En présence de dysphonie, d’encombrement pharyngé ou de dyspnée, la recommandation SFORL privilégie une fibroscopie souple spécialisée avant l’examen à l’abaisse-langue. L’examen oral reste prudent, assis et avec les moyens d’aspiration et de secours adaptés.',
    'Ne pas forcer la bouche d’un enfant en détresse ni improviser une ponction d’une masse pharyngée. L’évaluation des voies aériennes difficiles et les gestes invasifs relèvent de professionnels équipés.'
), (3,34,36))
l.add('L’approche syndromique distingue {infection localisée, extension profonde et autre tuméfaction}. Elle évite de confondre une adénite accessible avec une atteinte péripharyngée. Une évolution atypique doit faire reprendre le diagnostic.', table(['Profil','Question à résoudre'], [
    ['Ganglion latéral douloureux, sans signe pharyngé ou respiratoire profond','S’agit-il d’une adénite simple ou collectée ? La leçon dédiée à l’adénite précise ce parcours.'],
    ['Trismus, odynophagie et bombement péri-amygdalien','Existe-t-il un abcès péri-amygdalien et une extension vers les espaces voisins ?'],
    ['Torticolis fébrile, dysphagie ou signes pharyngés discrets','Existe-t-il une atteinte rétro- ou parapharyngée ?'],
    ['Plancher buccal induré avec langue déplacée','Existe-t-il une angine de Ludwig et une menace des voies aériennes ?'],
    ['Sepsis avec atteinte de plusieurs espaces, douleur thoracique ou crépitation','Existe-t-il une cellulite extensive, une nécrose ou une médiastinite ?'],
    ['Masse persistante après résolution de l’infection','Existe-t-il une lésion sous-jacente, notamment tumorale ou congénitale ?']
]), (3,34,36))
l.add('Le {diagnostic positif} combine clinique et cartographie du foyer. L’imagerie précise l’infiltration, les collections et les complications. La recherche du germe oriente ensuite le traitement.', paras(
    'L’infection profonde reste une suspicion clinique urgente avant d’être une image. Ni l’absence de fluctuation à la peau ni une cavité buccale peu impressionnante ne permettent de l’écarter chez un patient symptomatique.',
    'Le scanner injecté montre les espaces atteints et les lésions potentiellement drainables. Une image de liquide avec rehaussement périphérique soutient une collection, mais elle ne constitue pas une preuve absolue de pus. Le radiologue et le chirurgien rapprochent les images de la clinique.',
    'Le prélèvement profond ou opératoire permet culture et antibiogramme. Un frottis superficiel ne remplace pas un prélèvement du foyer. Les prélèvements utiles précèdent idéalement l’antibiothérapie, à condition de ne pas retarder un traitement urgent.',
    'Une suspicion de thrombose jugulaire, d’atteinte vasculaire ou de médiastinite modifie la cartographie et les équipes impliquées. Le diagnostic ne se limite alors plus à nommer un abcès cervical.'
), (3,34,35,36))
l.add('Les {examens complémentaires} répondent à une question précise. Le premier bilan apprécie le retentissement, puis l’imagerie cartographie l’atteinte profonde. Une échographie superficielle ne remplace pas ce bilan lorsqu’une extension profonde est suspectée.',
    '<h3>9.a — Examen de référence et confirmation</h3>' + paras('La tomodensitométrie injectée cartographie l’infection profonde ; elle n’est pas un test pathognomonique du pus. Pour une infection péripharyngée ou une cellulite cervicale profonde extensive, la synthèse SPILF prévoit une acquisition cervico-thoracique. Le prélèvement profond avec culture et antibiogramme documente le germe, lorsque le geste est indiqué et réalisable.') +
    table(['Résultat','Interprétation','Conduite'], [
        ['Infiltration sans collection nette','La cellulite peut être non collectée ou en cours d’évolution.','Adapter le traitement et la surveillance au retentissement.'],
        ['Zone liquidienne avec rehaussement périphérique','Une collection est possible ; le scanner ne prouve pas toujours le pus.','Confronter à la clinique et discuter le drainage.'],
        ['Gaz, extension médiastinale ou complication vasculaire','L’infection comporte des critères de gravité ou une complication.','Mobiliser les équipes adaptées et traiter le foyer sans délai.'],
        ['Culture et antibiogramme disponibles','Le germe et sa sensibilité orientent le choix.','Adapter le traitement sans oublier un foyer insuffisamment contrôlé.']
    ]) +
    '<h3>9.b — Premier bilan</h3>' + paras('Le bilan hospitalier adapte hémogramme, marqueurs inflammatoires, fonction rénale, électrolytes et autres examens aux signes de gravité. Il prépare aussi contraste, anesthésie et prescription. Des hémocultures sont indiquées en cas de sepsis. Aucun prélèvement ni résultat biologique ne doit différer les gestes vitaux.') +
    '<h3>9.c — Alternatives selon la question clinique</h3>' + paras('L’échographie aide pour une adénite superficielle ou une collection accessible. Elle ne suffit pas à exclure une atteinte profonde derrière le pharynx. Une autre modalité, notamment l’imagerie par résonance magnétique, peut être discutée pour une question particulière si elle reste compatible avec l’urgence. Grossesse, fonction rénale et antécédent de réaction au contraste nécessitent une discussion bénéfice-risque adaptée.') +
    '<h3>9.d — Seconde intention et évolution défavorable</h3>' + paras('Une aggravation, une persistance des signes ou une réponse insuffisante conduit à vérifier drainage, germe, résistance, dose et extension. Un contrôle d’imagerie répond à cette évolution ; il ne remplace pas une réévaluation clinique immédiate.'), (34,35,36,38))
l.add('L’{arbre décisionnel} relie la gravité au contrôle du foyer. Une forme compliquée nécessite une action immédiate. Un essai médical exclusif éventuel reste une décision hospitalière surveillée.', steps(
    'Si les voies aériennes sont menacées ou si un sepsis est présent, alors mobiliser les équipes d’urgence et commencer la stabilisation avec l’antibiothérapie appropriée, sans attendre une confirmation complète.',
    'Si l’état permet l’imagerie, alors cartographier le cou et le thorax pour préciser le foyer, les collections et les complications.',
    'Si une forme extensive, une nécrose, une complication ou un foyer nécessitant évacuation est identifié, alors organiser le contrôle chirurgical adapté avec prélèvements.',
    'Si l’infection est localisée et non compliquée, alors l’équipe spécialisée peut retenir un traitement médical initial avec surveillance étroite et réévaluation programmée.',
    'Si la réponse est insuffisante ou si le patient s’aggrave, alors réévaluer immédiatement le foyer et le besoin de drainage ; ne pas attendre un délai théorique devant une dégradation.',
    'Si l’évolution est favorable, alors adapter aux cultures, vérifier la déglutition et organiser le relais et le suivi avec une durée individualisée.'
), (34,35,36))

c = coamoxi(l)
k = clindamycine(l)
l.add('La {prise en charge en Suisse} associe hospitalisation, protection des fonctions vitales et antibiothérapie parentérale adaptée. Le contrôle du foyer est organisé sans délai selon la gravité. Les doses, le relais et la durée sont réévalués avec les résultats et l’évolution.',
    '<h3>11.A — Buts et priorités</h3>' + paras('Préserver respiration et perfusion, traiter l’infection et contrôler le foyer. L’oto-rhino-laryngologiste ou le chirurgien maxillo-facial, l’anesthésiste et l’infectiologue coordonnent les décisions. Une extension thoracique requiert aussi l’expertise correspondante.') +
    '<h3>11.B — Moyens dans l’ordre clinique</h3>' + paras('Le patient reste surveillé ; oxygénation, accès veineux et correction du retentissement sont adaptés à son état. Une impossibilité de déglutir impose d’éviter les prises orales forcées. L’hydratation et l’antalgie sont organisées selon le terrain et le projet anesthésique.', 'Les antalgiques dépresseurs respiratoires et les anti-inflammatoires non stéroïdiens ne constituent pas une réponse ambulatoire à une suspicion d’infection profonde. L’indication d’un corticoïde dépend d’une situation précise et d’un avis spécialisé ; il ne remplace ni les voies aériennes, ni l’antibiothérapie, ni le drainage.', 'La prescription probabiliste couvre les germes attendus du siège et du terrain, puis se resserre selon la documentation. L’association amoxicilline–acide clavulanique est une option décrite dans les sources européennes. La spécialité et les doses suisses sont détaillées ici : ' + c + '.', 'Devant une allergie, documenter manifestations, délai et gravité. Une anaphylaxie ou une réaction cutanée sévère n’équivaut pas à une simple intolérance digestive. La notice Co-Amoxi-Mepha contre-indique l’emploi en cas d’hypersensibilité aux pénicillines ou céphalosporines ; ne pas appliquer une alternative française sans confronter la notice et la situation du patient.', 'La place éventuelle de la clindamycine est précisée dans la fenêtre ' + k + '. Elle nécessite une évaluation du spectre et des résistances. Une allergie grave, une infection extensive, un choc ou une immunodépression impose un avis infectiologique urgent pour le schéma complet ; cette fenêtre ne prescrit pas une substitution universelle.', 'Le drainage ou le débridement traite les collections et tissus concernés. La voie dépend des espaces et des rapports vasculaires. Une infection profonde n’est jamais ponctionnée à l’aveugle en consultation non équipée. Le foyer dentaire, pharyngé ou salivaire est également traité.', 'Un traitement médical exclusif peut être retenu dans des formes sélectionnées non compliquées, avec contrôle hospitalier et réévaluation. Le seuil pour opérer dépend du terrain, de l’évolution et de l’équipe. Cette possibilité ne s’étend pas à une cellulite nécrosante ou à une menace respiratoire.', 'Chez l’enfant, l’essai médical se décide avec l’équipe pédiatrique et la possibilité d’un geste. Les doses sont pondérales et la présentation injectable de clindamycine décrite est contre-indiquée chez nouveau-nés et prématurés. Pendant grossesse ou allaitement, appliquer les précautions des notices et coordonner avec les spécialistes sans différer une prise en charge vitale.') +
    '<h3>11.C — Surveillance et adaptation</h3>' + paras('Surveiller respiration, température, douleur, déglutition, tuméfaction, diurèse et tolérance des traitements. La fréquence dépend de l’instabilité ; une menace respiratoire nécessite un secteur permettant une surveillance continue et une intervention immédiate. Vérifier les cultures et l’efficacité du contrôle du foyer. Toute dégradation entraîne une nouvelle décision immédiate.', 'La durée dépend du foyer, du drainage et des complications ; un abcès localisé drainé et une médiastinite n’ont pas le même parcours. Le relais oral suppose une amélioration et une déglutition fiable. Les durées des guides étrangers ne sont pas présentées comme une ordonnance suisse universelle.', 'Le CHUV indique que Firstline a remplacé son guide papier depuis décembre 2025. Ses recommandations institutionnelles actuelles n’ont pas été lues dans Firstline pour cette leçon : le protocole local et l’avis infectiologique restent à vérifier au lit du patient. Le document HUG 2019 ne vaut pas une prescription institutionnelle actuelle.') +
    '<h3>11.D — Pronostic et sortie</h3>' + paras('Le pronostic dépend du contrôle du foyer et des complications respiratoires, vasculaires, septiques ou médiastinales. Aucun taux de mortalité universel n’est appliqué à l’ensemble des infections profondes. La sortie suppose des voies aériennes sûres, une évolution locale et générale favorable, un foyer contrôlé et une prise orale ou un traitement relais organisés. Le patient reçoit un suivi daté et les consignes de retour urgent.'), (3,34,35,36,37,38,39))
l.add('La {prévention des récidives et des séquelles} passe par le traitement du foyer initial. Le suivi vérifie la récupération et la disparition des signes infectieux. Une anomalie persistante exige une nouvelle recherche.', paras(
    'Organiser les soins dentaires ou le suivi pharyngé et salivaire lorsque ces territoires sont en cause. Expliquer au patient le plan de traitement et les signes imposant un retour immédiat : gêne respiratoire, salive non déglutie, aggravation du gonflement ou douleur thoracique.',
    'Après l’épisode aigu, contrôler la déglutition et le territoire atteint. Une masse persistante, une récidive au même endroit ou une évolution inhabituelle justifie une investigation d’une cause sous-jacente. L’amélioration sous antibiotique ne prouve pas que toute lésion résiduelle soit bénigne.',
    'Le suivi prend aussi en compte les complications des traitements. Une diarrhée persistante après l’antibiothérapie, une éruption grave ou une atteinte hépatique suspectée nécessite une évaluation ; le patient doit savoir à qui s’adresser.'
), (3,34,38,39))
l.add('Les {points clés} sont le siège profond, le retentissement et l’évolution. Une atteinte modeste en surface peut cacher une infection importante. La réponse attendue associe surveillance, antibiotique adapté et contrôle du foyer lorsque celui-ci est nécessaire.', steps(
    'Évoquer une infection profonde devant torticolis fébrile, trismus récent, dysphagie ou signes laryngés.',
    'Sécuriser les fonctions vitales avant un examen qui risquerait de retarder les gestes nécessaires.',
    'Préciser le foyer et son extension avec l’équipe spécialisée.',
    'Documenter le germe sans différer le traitement d’une urgence.',
    'Adapter antibiotique, présentation et dose aux reins, au poids, au terrain et aux résultats.',
    'Réévaluer rapidement un foyer insuffisamment contrôlé et organiser le suivi après amélioration.'
), (3,34,35,36,38,39))
l.quiz([
    ('Un cou peu rouge exclut-il une infection profonde ?', 'Non. Le foyer peut être peu visible à la surface ; dysphagie, trismus, torticolis fébrile ou signes respiratoires imposent un raisonnement plus profond.'),
    ('Faut-il attendre le scanner devant une menace respiratoire ?', 'Non. La stabilisation et l’intervention de l’équipe compétente priment ; l’imagerie est organisée dès que la sécurité le permet.'),
    ('Quel piège comporte l’examen oral forcé ?', 'Il peut déstabiliser un patient dont les voies aériennes sont menacées. L’examen doit être prudent et réalisé dans un cadre adapté.'),
    ('Une échographie superficielle normale suffit-elle à exclure une atteinte rétropharyngée ?', 'Non. Elle ne remplace pas la cartographie adaptée d’une suspicion d’atteinte profonde.'),
    ('Une image évoquant une collection prouve-t-elle toujours la présence de pus ?', 'Non. L’interprétation doit être confrontée à la clinique et à l’avis spécialisé.'),
    ('Toute infection localisée exige-t-elle immédiatement une chirurgie ?', 'Non. Des formes sélectionnées non compliquées peuvent recevoir un traitement médical initial sous surveillance hospitalière. Une aggravation impose une nouvelle décision sans attendre.'),
    ('Cette possibilité s’applique-t-elle à une cellulite nécrosante ?', 'Non. Une forme extensive, nécrosante ou compliquée requiert un contrôle rapide du foyer avec l’équipe chirurgicale.'),
    ('Les prélèvements doivent-ils retarder les antibiotiques lors d’un sepsis ?', 'Non. Les obtenir avant le traitement si cela ne retarde pas l’urgence ; les cultures orienteront ensuite l’adaptation.'),
    ('Que doivent faire rechercher douleur thoracique ou aggravation respiratoire ?', 'Une extension médiastinale ou une complication pulmonaire, notamment dans un contexte de thrombophlébite jugulaire infectée.'),
    ('Les flacons 1000/200 et 1000/100 sont-ils interchangeables sur la seule masse d’amoxicilline ?', 'Non. Le rapport au clavulanate diffère ; indication, âge et fonction rénale doivent être vérifiés.'),
    ('Peut-on injecter la clindamycine concentrée en bolus intraveineux ?', 'Non. La dilution et la vitesse de perfusion de la notice doivent être respectées ; une administration trop rapide peut provoquer un accident grave.'),
    ('Une allergie aux pénicillines rend-elle la clindamycine automatiquement adaptée ?', 'Non. Il faut caractériser l’allergie, la gravité de l’infection et les sensibilités ; un schéma complet spécialisé peut être nécessaire.'),
    ('La présentation injectable de clindamycine décrite convient-elle au nouveau-né ?', 'Non. Elle est contre-indiquée chez nouveau-nés et prématurés en raison de l’alcool benzylique.'),
    ('La disparition de la fièvre suffit-elle pour ignorer une masse persistante ?', 'Non. La résolution clinique et le foyer doivent être contrôlés ; une masse résiduelle ou une récidive peut révéler une autre cause.')
], (3,34,35,36,38,39))
l.write()
